import {
    Table,
    BooleanColumn,
    ConditionsColumn,
    ScriptColumn,
    StringColumn,
    ReferenceColumn,
    ChoiceColumn,
    RadioColumn,
} from '../../db'

export const sys_security_acl = Table({
    name: 'sys_security_acl',
    extends: 'sys_metadata',
    schema: {
        name: StringColumn({ mandatory: true }),
        active: BooleanColumn({ default: true }),
        advanced: BooleanColumn({ default: false }),
        script: ScriptColumn({}),
        admin_overrides: BooleanColumn({ default: true }),
        decision_type: ChoiceColumn({
            choices: {
                allow: { label: 'Allow If', sequence: 1, language: 'en' },
                deny: { label: 'Deny Unless', sequence: 2, language: 'en' },
            },
            default: 'allow',
        }),
        type: ReferenceColumn({ mandatory: true, referenceTable: 'sys_security_type' }),
        condition: ConditionsColumn({}),
        applies_to: ConditionsColumn({}),
        operation: ReferenceColumn({ mandatory: true, referenceTable: 'sys_security_operation' }),
        security_attribute: ReferenceColumn({ mandatory: false, referenceTable: 'sys_security_attribute' }),
        description: StringColumn({}),
        local_or_existing: RadioColumn({ default: 'Local' }),
    },
})
